package net.officefloor.hq.app.holiday;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;
import java.time.LocalDate;
import java.util.List;
import net.officefloor.hq.app.SignedIn;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.http.HttpStatus;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.ResponseStatus;
import org.springframework.web.bind.annotation.RestController;

@RestController
@RequestMapping("/api/sheets/{sheetId}/holidays")
@Validated
public class HolidayController {

    /** What the screen is told about a holiday: its date. */
    public record HolidayView(long id, LocalDate date) {

        static HolidayView of(Holiday holiday) {
            return new HolidayView(holiday.getId(), holiday.getDate());
        }
    }

    /** A holiday as entered on the form: a date, required. */
    public record HolidayForm(@NotNull LocalDate date) {
    }

    private final HolidayService service;

    public HolidayController(HolidayService service) {
        this.service = service;
    }

    /** The sheet's holidays by date. */
    @GetMapping
    public List<HolidayView> list(
            @PathVariable @NotBlank @Size(max = 64) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId) {
        return service.list(sheetId).stream().map(HolidayView::of).toList();
    }

    /** Add a holiday to the sheet. */
    @PostMapping
    public HolidayView add(
            @PathVariable @NotBlank @Size(max = 64) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @RequestHeader(SignedIn.HEADER) @NotBlank @Size(max = 200) String user,
            @RequestBody @Valid HolidayForm form) {
        return HolidayView.of(service.add(sheetId, SignedIn.name(user), form.date()));
    }

    /** Another user added the date between the check and the write: the unique index refuses it. */
    @ExceptionHandler(DataIntegrityViolationException.class)
    @ResponseStatus(HttpStatus.CONFLICT)
    public void dateTaken() {
    }
}
package net.officefloor.hq.app.holiday;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import java.time.LocalDate;

/** A holiday on a sheet: a date, on the sheet's list at most once. */
@Entity
@Table(name = "holiday")
public class Holiday {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "holiday_date", nullable = false)
    private LocalDate date;

    protected Holiday() {
    }

    public Holiday(String sheetId, LocalDate date) {
        this.sheetId = sheetId;
        this.date = date;
    }

    public Long getId() {
        return id;
    }

    public String getSheetId() {
        return sheetId;
    }

    public LocalDate getDate() {
        return date;
    }
}
package net.officefloor.hq.app.holiday;

import java.time.LocalDate;
import java.util.List;
import org.springframework.data.jpa.repository.JpaRepository;

public interface HolidayRepository extends JpaRepository<Holiday, Long> {

    /** The sheet's holidays by date. */
    List<Holiday> findBySheetIdOrderByDateAsc(String sheetId);

    /** Whether the date is already a holiday on the sheet. */
    boolean existsBySheetIdAndDate(String sheetId, LocalDate date);
}
package net.officefloor.hq.app.holiday;

import java.time.LocalDate;
import java.util.List;
import java.util.Set;
import java.util.stream.Collectors;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.claim.BusinessDays;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.rollup.Rollups;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

/** The holidays on a sheet: listed, added, and the days a due-by does not count as business days. */
@Service
public class HolidayService {

    private final HolidayRepository holidays;
    private final SheetService sheets;
    private final ClaimRepository claims;
    private final Rollups rollups;
    private final Audit audit;

    public HolidayService(HolidayRepository holidays, SheetService sheets, ClaimRepository claims, Rollups rollups,
            Audit audit) {
        this.holidays = holidays;
        this.sheets = sheets;
        this.claims = claims;
        this.rollups = rollups;
        this.audit = audit;
    }

    /** The sheet's holidays by date. */
    @Transactional(readOnly = true)
    public List<Holiday> list(String sheetId) {
        return holidays.findBySheetIdOrderByDateAsc(sheetId);
    }

    /**
     * Add a holiday to the sheet; refused when the date is already on its list. Every claim's due-by on
     * the sheet is worked out again against the holidays now, and the figures that moves are audited.
     */
    @Transactional
    public Holiday add(String sheetId, String user, LocalDate date) {
        // Take the sheet's lock first, so the same date added twice at once cannot both pass the check.
        sheets.lock(sheetId);
        if (holidays.existsBySheetIdAndDate(sheetId, date)) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "That date is already a holiday on this sheet.");
        }
        Rollups.Rollup before = rollups.take(sheetId);
        Holiday saved = holidays.saveAndFlush(new Holiday(sheetId, date));
        Set<LocalDate> days = days(sheetId);
        for (Claim claim : claims.findBySheetIdOrderByIdDesc(sheetId)) {
            claim.workOutDueBy(days);
        }
        claims.flush();
        audit.recordOnCommit("HOLIDAY_ADDED sheet=" + sheetId + " by=" + user + " date=" + date);
        rollups.audit(sheetId, user, before);
        return saved;
    }

    /** The terms-th business day after a date, skipping the holidays on the sheet now (see {@link BusinessDays#dueBy}). */
    @Transactional(readOnly = true)
    public LocalDate dueBy(String sheetId, LocalDate date, int terms) {
        return BusinessDays.dueBy(date, terms, days(sheetId));
    }

    private Set<LocalDate> days(String sheetId) {
        return holidays.findBySheetIdOrderByDateAsc(sheetId).stream().map(Holiday::getDate)
                .collect(Collectors.toSet());
    }
}
-- A holiday on a sheet: a date, on the sheet's list at most once. A claim's due-by, fixed when it
-- is added, is moved past the holidays on the list then.
CREATE TABLE holiday (
    id           BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id     VARCHAR(64) NOT NULL REFERENCES sheet (id),
    holiday_date DATE        NOT NULL
);
CREATE UNIQUE INDEX holiday_sheet_date ON holiday (sheet_id, holiday_date);
-- A claim's tags: trimmed, lower case, no repeats, sorted and comma separated (null: none); and every
-- tag it has ever carried, in the same form (null: none), so the sheet lists each tag ever used on it.
ALTER TABLE claim ADD COLUMN tags VARCHAR(2000);
ALTER TABLE claim ADD COLUMN tags_used VARCHAR(4000);
import { HttpClient } from '@angular/common/http';
import { Injectable, inject } from '@angular/core';
import { firstValueFrom } from 'rxjs';

/** A holiday on the sheet: a claim's due-by falling on one is moved to the next day that is not one. */
export interface HolidayView {
  id: number;
  /** yyyy-mm-dd; on the sheet's list at most once. */
  date: string;
}

// The sheet's holidays, read from and written to the store.
@Injectable({ providedIn: 'root' })
export class HolidaysApi {
  private readonly http = inject(HttpClient);

  /** The sheet's holidays by date. */
  list(sheet: string): Promise<HolidayView[]> {
    return firstValueFrom(this.http.get<HolidayView[]>(this.url(sheet)));
  }

  /** Add a holiday; refused when the date is already on the list. */
  add(sheet: string, date: string): Promise<HolidayView> {
    return firstValueFrom(this.http.post<HolidayView>(this.url(sheet), { date }));
  }

  private url(sheet: string): string {
    return `/api/sheets/${encodeURIComponent(sheet)}/holidays`;
  }
}
import { Component, effect, inject, signal, untracked } from '@angular/core';
import { HolidayView, HolidaysApi } from '../../core/holidays';
import { Session } from '../../core/session';

const DATE = /^\d{4}-\d{2}-\d{2}$/;

// The sheet's holidays, listed by date, and a form to add one; a date already on the list is refused.
// A claim's due-by, fixed when it is added, is moved past the holidays on the list then.
@Component({
  selector: 'app-holidays',
  template: `
    <section aria-labelledby="holidays-heading">
      <h2 id="holidays-heading">Holidays</h2>
      <form (submit)="add($event)" aria-label="Add a holiday">
        <label for="holiday-date">Date</label>
        <input
          id="holiday-date"
          type="date"
          data-testid="holiday-date"
          [value]="date()"
          (input)="date.set(value($event)); error.set(null)"
        />
        <button type="submit" data-testid="holiday-add">Add holiday</button>
        @if (error(); as message) {
          <p role="alert" data-testid="holiday-error">{{ message }}</p>
        }
      </form>
      <ul aria-label="Holidays">
        @for (h of holidays(); track h.id) {
          <li [attr.data-testid]="'holiday-row-' + h.date">
            <span data-testid="holiday-row-date">{{ h.date }}</span>
          </li>
        }
      </ul>
    </section>
  `,
})
export class Holidays {
  private readonly session = inject(Session);
  private readonly api = inject(HolidaysApi);

  protected readonly holidays = signal<HolidayView[]>([]);
  protected readonly date = signal('');
  protected readonly error = signal<string | null>(null);
  /** A submit is waiting for its answer: a second submit meanwhile is ignored. */
  private busy = false;

  constructor() {
    // Every sheet load re-reads the sheet's holidays from the store.
    effect(() => {
      const sheet = this.session.sheet();
      const loads = this.session.loads();
      untracked(() => {
        this.holidays.set([]);
        this.error.set(null);
        if (sheet) void this.reload(sheet, loads);
      });
    });
  }

  protected value(event: Event): string {
    return (event.target as HTMLInputElement).value;
  }

  protected async add(event: Event): Promise<void> {
    event.preventDefault();
    if (this.busy) return;
    this.error.set(null);
    const sheet = this.session.sheet();
    if (!sheet) return;
    const date = this.date().trim();
    if (!DATE.test(date)) {
      this.error.set('Pick a date for the holiday.');
      return;
    }
    if (this.holidays().some((h) => h.date === date)) {
      this.error.set(`${date} is already a holiday.`);
      return;
    }
    this.busy = true;
    try {
      const saved = await this.api.add(sheet, date);
      this.holidays.update((all) => [...all, saved].sort((a, b) => a.date.localeCompare(b.date)));
      this.date.set('');
    } catch {
      this.error.set(`${date} could not be added as a holiday: it may already be on the list.`);
    } finally {
      this.busy = false;
    }
  }

  private async reload(sheet: string, loads: number): Promise<void> {
    const holidays = await this.api.list(sheet);
    // A later load may have started while this one was in flight: only the latest is shown.
    if (this.session.sheet() === sheet && this.session.loads() === loads) this.holidays.set(holidays);
  }
